class Solution:
    def minSwap(self, nums1: List[int], nums2: List[int]) -> int:
        from functools import lru_cache
        n = len(nums1)
        @lru_cache(maxsize=None)
        def dfs(i, p1, p2):
            if i == n:
                return 0
            best = float('inf')
            if nums1[i] > p1 and nums2[i] > p2:
                best = dfs(i + 1, nums1[i], nums2[i])
            if nums2[i] > p1 and nums1[i] > p2:
                best = min(best, 1 + dfs(i + 1, nums2[i], nums1[i]))
            return best
        return dfs(1, nums1[0], nums2[0])

