class Solution {
public:
    int n;
    vector<int> a, b;
    map<tuple<int,int,int>,int> memo;
    int dfs(int i, int p1, int p2) {
        if (i == n) return 0;
        auto key = make_tuple(i, p1, p2);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int best = INT_MAX;
        if (a[i] > p1 && b[i] > p2) best = dfs(i + 1, a[i], b[i]);
        if (b[i] > p1 && a[i] > p2) best = min(best, 1 + dfs(i + 1, b[i], a[i]));
        return memo[key] = best;
    }
    int minSwap(vector<int>& nums1, vector<int>& nums2) {
        a = nums1; b = nums2; n = nums1.size();
        return dfs(1, nums1[0], nums2[0]);
    }
};

