class Solution {
public:
    int minSwap(vector<int>& nums1, vector<int>& nums2) {
        int keep = 0, swp = 1, n = nums1.size();
        for (int i = 1; i < n; i++) {
            int nk = INT_MAX, ns = INT_MAX;
            if (nums1[i] > nums1[i-1] && nums2[i] > nums2[i-1]) {
                nk = min(nk, keep);
                ns = min(ns, swp + 1);
            }
            if (nums1[i] > nums2[i-1] && nums2[i] > nums1[i-1]) {
                nk = min(nk, swp);
                ns = min(ns, keep + 1);
            }
            keep = nk; swp = ns;
        }
        return min(keep, swp);
    }
};

